<?php
$entity = is_string($_GET['entity'] ?? null) ? $_GET['entity'] : 'categorias';
if (!in_array($entity,['categorias','servicios','horarios'],true)) throw new DomainException('Módulo inválido.');
$editId = isset($_GET['edit']) ? positive($_GET['edit']) : null;
$rows = match ($entity) {
 'categorias' => q('SELECT * FROM categorias ORDER BY id DESC')->fetchAll(),
 'servicios' => q('SELECT s.*,c.nombre AS categoria FROM servicios s JOIN categorias c ON c.id=s.categoria_id ORDER BY s.id DESC')->fetchAll(),
 'horarios' => q('SELECT h.*,s.nombre AS servicio FROM horarios h JOIN servicios s ON s.id=h.servicio_id ORDER BY h.fecha DESC,h.hora_inicio DESC')->fetchAll(),
};
$edit = null;
if ($editId) {
    foreach ($rows as $row) if ((int)$row['id'] === $editId) $edit = $row;
    if (!$edit) throw new DomainException('Registro no encontrado.');
}
$cats = q("SELECT id,nombre FROM categorias WHERE estado='ACTIVO' ORDER BY nombre")->fetchAll();
$services = q("SELECT s.id,s.nombre FROM servicios s JOIN categorias c ON c.id=s.categoria_id WHERE s.estado='ACTIVO' AND c.estado='ACTIVO' ORDER BY s.nombre")->fetchAll();
$label = ['categorias'=>'Categorías','servicios'=>'Servicios','horarios'=>'Horarios'][$entity];
?>
<main class="container section"><span class="eyebrow">CENTRO DE CONTROL</span><h1>Administración</h1><p class="lead">Gestiona servicios, disponibilidad y citas desde un solo lugar.</p>
<div class="tabs"><a class="<?= $entity==='categorias'?'active':'' ?>" href="<?= url('admin',['entity'=>'categorias']) ?>">Categorías</a><a class="<?= $entity==='servicios'?'active':'' ?>" href="<?= url('admin',['entity'=>'servicios']) ?>">Servicios</a><a class="<?= $entity==='horarios'?'active':'' ?>" href="<?= url('admin',['entity'=>'horarios']) ?>">Horarios</a><a href="<?= url('admin-reservas') ?>">Reservas ↗</a><a href="<?= url('admin-centers') ?>">Cuentas ↗</a></div>
<div class="admin-grid"><section class="panel"><h2><?= $edit ? 'Editar' : 'Crear' ?> <?= e(strtolower($label)) ?></h2><form method="post" action="<?= url('admin-save') ?>"><?= csrf_field() ?><input type="hidden" name="entity" value="<?= e($entity) ?>"><?php if ($edit): ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php endif; ?>
<?php if ($entity === 'categorias'): ?><label>Nombre<input required name="nombre" maxlength="100" value="<?= e($edit['nombre'] ?? '') ?>"></label><label>Descripción<textarea required name="descripcion" maxlength="500" rows="4"><?= e($edit['descripcion'] ?? '') ?></textarea></label>
<?php elseif ($entity === 'servicios'): ?><label>Categoría<select required name="categoria_id"><option value="">Selecciona</option><?php foreach ($cats as $cat): ?><option value="<?= e($cat['id']) ?>" <?= (int)($edit['categoria_id'] ?? 0)===(int)$cat['id']?'selected':'' ?>><?= e($cat['nombre']) ?></option><?php endforeach; ?></select></label><label>Nombre<input required name="nombre" maxlength="120" value="<?= e($edit['nombre'] ?? '') ?>"></label><label>Descripción<textarea required name="descripcion" maxlength="2000" rows="4"><?= e($edit['descripcion'] ?? '') ?></textarea></label><div class="form-grid"><label>Precio (USD)<input required type="number" name="precio" min="0" max="99999999" step="0.01" value="<?= e($edit['precio'] ?? '') ?>"></label><label>Duración (min)<input required type="number" name="duracion_min" min="1" max="1440" value="<?= e($edit['duracion_min'] ?? '') ?>"></label></div>
<?php else: ?><label>Servicio<select required name="servicio_id"><option value="">Selecciona</option><?php foreach ($services as $s): ?><option value="<?= e($s['id']) ?>" <?= (int)($edit['servicio_id'] ?? 0)===(int)$s['id']?'selected':'' ?>><?= e($s['nombre']) ?></option><?php endforeach; ?></select></label><label>Fecha<input required type="date" name="fecha" value="<?= e($edit['fecha'] ?? '') ?>"></label><div class="form-grid"><label>Hora de inicio<input required type="time" name="hora_inicio" value="<?= e(substr($edit['hora_inicio'] ?? '',0,5)) ?>"></label><label>Hora de fin<input required type="time" name="hora_fin" value="<?= e(substr($edit['hora_fin'] ?? '',0,5)) ?>"></label></div><label>Cupos totales<input required type="number" name="cupos_total" min="1" max="1000" value="<?= e($edit['cupos_total'] ?? '') ?>"></label><p class="small">Con reservas existentes solo se pueden ajustar cupos, sin bajar de los ocupados.</p>
<?php endif; ?><button class="button full" type="submit">Guardar</button><?php if ($edit): ?><a class="back" href="<?= url('admin',['entity'=>$entity]) ?>">Cancelar edición</a><?php endif; ?></form></section>
<section class="admin-list"><h2><?= e($label) ?> <span class="count"><?= count($rows) ?></span></h2><?php foreach ($rows as $row): ?><article class="admin-item"><div><span class="pill <?= $row['estado']==='INACTIVO'?'muted':'' ?>"><?= e($row['estado']) ?></span><h3><?= e($row['nombre'] ?? $row['servicio']) ?></h3>
<?php if ($entity==='horarios'): ?><p><?= e($row['fecha']) ?> · <?= e(substr($row['hora_inicio'],0,5)) ?>–<?= e(substr($row['hora_fin'],0,5)) ?> · <?= e($row['cupos_disponibles']) ?>/<?= e($row['cupos_total']) ?> cupos</p><?php elseif ($entity==='servicios'): ?><p><?= e($row['categoria']) ?> · $<?= e($row['precio']) ?> · <?= e($row['duracion_min']) ?> min</p><?php else: ?><p><?= e($row['descripcion']) ?></p><?php endif; ?></div><div class="item-actions"><a class="button-outline" href="<?= url('admin',['entity'=>$entity,'edit'=>$row['id']]) ?>">Editar</a><form method="post" action="<?= url('admin-toggle') ?>"><?= csrf_field() ?><input type="hidden" name="entity" value="<?= e($entity) ?>"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="link-button" type="submit"><?= $row['estado']==='ACTIVO'?'Desactivar':'Activar' ?></button></form></div></article><?php endforeach; ?><?php if (!$rows): ?><p class="empty">No hay registros.</p><?php endif; ?></section></div></main>
